// Package protocol is the relay channel of schema/protocol.v1.json for the Go relay (plan-relay-go D7, seam S2).
// protocol.g.go is generated by schema/codegen.mjs (types, close codes, one check and one writer per message);
// this file is the protocol-agnostic part: a strict JSON reader with the accept set of the C# relay's
// ProtocolJson.ParseRelay (ProtocolJson.cs:109-149) and a JSON writer.
//
// Strict means: one JSON value (RFC 8259) with nothing but whitespace after it; member names compared exactly; no
// null anywhere; no unknown, missing or wrongly typed member; integers written without fraction or exponent, within
// ±(2^53-1); strings valid UTF-8 with no lone UTF-16 surrogate where they are read; nesting at most 64 deep
// (JsonDocument's default).
//
// A repeated member name follows the C# parser, measured 2026-11-20 against ProtocolJson.ParseRelay (protocol_test.go
// TestDuplicateMembersAsCsharp): the LAST "type" names the message and earlier "type"s are ignored; a null in any
// occurrence refuses; every occurrence of a field must be of its JSON type (a valid string, an int64 literal, a bool,
// an allowed enum value — System.Text.Json reads each one), and only the last one gets the schema's pattern /
// maxLength / minimum / safe-range checks (ProtocolValidation runs on the deserialized record).
package protocol

import (
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"unicode/utf16"
	"unicode/utf8"
)

// RelayMessage is a relay control message (plan-relay S1).
type RelayMessage interface {
	RelayType() string
	write(w *writer)
}

// Kind of a parse result.
type Kind int

const (
	// Ok: a valid relay message.
	Ok Kind = iota
	// Unknown: a well-formed object whose type is not a relay message.
	Unknown
	// Invalid: not JSON, wrong shape, or a constraint violation.
	Invalid
)

// Result of ParseRelay: Message for Ok, Type for Unknown, Reason for Invalid.
type Result struct {
	Kind    Kind
	Message RelayMessage
	Type    string
	Reason  string
}

const maxSafe = 1<<53 - 1
const maxDepth = 64

// ParseRelay parses one relay control text message. It never panics on any input.
func ParseRelay(text []byte) Result {
	p := parser{s: text}
	p.ws()
	v, err := p.value(0)
	if err == nil {
		p.ws()
		if p.i != len(p.s) {
			err = errors.New("trailing data")
		}
	}
	if err != nil {
		return Result{Kind: Invalid, Reason: err.Error()}
	}
	o, isObj := v.(object)
	if !isObj {
		return Result{Kind: Invalid, Reason: "missing type"}
	}
	var t string
	switch last := o.last("type").(type) {
	case string:
		t = last
	case badString:
		return Result{Kind: Invalid, Reason: "type: lone surrogate"} // C# GetString throws
	default:
		return Result{Kind: Invalid, Reason: "missing type"}
	}
	check, known := relayChecks[t]
	if !known {
		return Result{Kind: Unknown, Type: t}
	}
	if containsNull(o) {
		return Result{Kind: Invalid, Reason: "null is not allowed"}
	}
	msg, err := check(o)
	if err != nil {
		return Result{Kind: Invalid, Reason: err.Error()}
	}
	return Result{Kind: Ok, Message: msg}
}

// MarshalRelay serializes m after checking it against the schema (C# SerializeRelay throws on a violation: a caller bug).
func MarshalRelay(m RelayMessage) ([]byte, error) {
	w := &writer{}
	m.write(w)
	if r := ParseRelay(w.b); r.Kind != Ok {
		return nil, fmt.Errorf("refusing to send %s: %s", m.RelayType(), r.Reason)
	}
	return w.b, nil
}

// ---------------------------------------------------------------------------------------------------- reading

type null struct{}

type number string // the literal, as written

// badString is a string holding a lone UTF-16 surrogate: legal JSON for JsonDocument, refused where it is read.
type badString struct{}

// object keeps every occurrence of each member name, in order.
type object struct{ m map[string][]any }

func (o object) last(name string) any {
	if vs := o.m[name]; len(vs) > 0 {
		return vs[len(vs)-1]
	}
	return nil
}

type parser struct {
	s []byte
	i int
}

func (p *parser) ws() {
	for p.i < len(p.s) {
		switch p.s[p.i] {
		case ' ', '\t', '\n', '\r':
			p.i++
		default:
			return
		}
	}
}

func (p *parser) value(depth int) (any, error) {
	if p.i >= len(p.s) {
		return nil, errors.New("unexpected end")
	}
	switch c := p.s[p.i]; {
	case c == '{':
		return p.object(depth + 1)
	case c == '[':
		return p.array(depth + 1)
	case c == '"':
		s, lone, err := p.str()
		if lone {
			return badString{}, err
		}
		return s, err
	case c == '-' || (c >= '0' && c <= '9'):
		return p.number()
	case p.lit("true"):
		return true, nil
	case p.lit("false"):
		return false, nil
	case p.lit("null"):
		return null{}, nil
	default:
		return nil, errors.New("not JSON")
	}
}

func (p *parser) lit(word string) bool {
	if strings.HasPrefix(string(p.s[p.i:min(len(p.s), p.i+len(word))]), word) {
		p.i += len(word)
		return true
	}
	return false
}

func (p *parser) object(depth int) (any, error) {
	if depth > maxDepth {
		return nil, errors.New("too deep")
	}
	p.i++ // {
	o := object{m: map[string][]any{}}
	p.ws()
	if p.i < len(p.s) && p.s[p.i] == '}' {
		p.i++
		return o, nil
	}
	for {
		p.ws()
		if p.i >= len(p.s) || p.s[p.i] != '"' {
			return nil, errors.New("expected a member name")
		}
		start := p.i
		k, lone, err := p.str()
		if err != nil {
			return nil, err
		}
		if lone {
			k = "\x00" + string(p.s[start:p.i]) // a name no member has: refused as unknown
		}
		p.ws()
		if p.i >= len(p.s) || p.s[p.i] != ':' {
			return nil, errors.New("expected ':'")
		}
		p.i++
		p.ws()
		v, err := p.value(depth)
		if err != nil {
			return nil, err
		}
		o.m[k] = append(o.m[k], v)
		p.ws()
		if p.i >= len(p.s) {
			return nil, errors.New("unexpected end")
		}
		switch p.s[p.i] {
		case ',':
			p.i++
		case '}':
			p.i++
			return o, nil
		default:
			return nil, errors.New("expected ',' or '}'")
		}
	}
}

func (p *parser) array(depth int) (any, error) {
	if depth > maxDepth {
		return nil, errors.New("too deep")
	}
	p.i++ // [
	var a []any
	p.ws()
	if p.i < len(p.s) && p.s[p.i] == ']' {
		p.i++
		return a, nil
	}
	for {
		p.ws()
		v, err := p.value(depth)
		if err != nil {
			return nil, err
		}
		a = append(a, v)
		p.ws()
		if p.i >= len(p.s) {
			return nil, errors.New("unexpected end")
		}
		switch p.s[p.i] {
		case ',':
			p.i++
		case ']':
			p.i++
			return a, nil
		default:
			return nil, errors.New("expected ',' or ']'")
		}
	}
}

func hex4(b []byte) (rune, bool) {
	if len(b) < 4 {
		return 0, false
	}
	v, err := strconv.ParseUint(string(b[:4]), 16, 32)
	return rune(v), err == nil
}

// str reads a string literal: escapes decoded, surrogate pairs joined. lone = it holds an escaped lone surrogate (legal
// JSON; refused where read). Raw control characters, bad escapes and invalid UTF-8 are errors (JsonDocument refuses them).
func (p *parser) str() (s string, lone bool, err error) {
	p.i++ // "
	var sb strings.Builder
	for {
		if p.i >= len(p.s) {
			return "", false, errors.New("unterminated string")
		}
		c := p.s[p.i]
		switch {
		case c == '"':
			p.i++
			return sb.String(), lone, nil
		case c < 0x20:
			return "", false, errors.New("control character in a string")
		case c == '\\':
			if p.i+1 >= len(p.s) {
				return "", false, errors.New("unterminated escape")
			}
			e := p.s[p.i+1]
			p.i += 2
			switch e {
			case '"', '\\', '/':
				sb.WriteByte(e)
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'u':
				r, ok := hex4(p.s[p.i:])
				if !ok {
					return "", false, errors.New("bad \\u escape")
				}
				p.i += 4
				if !utf16.IsSurrogate(r) {
					sb.WriteRune(r)
					break
				}
				if r < 0xDC00 && p.i+6 <= len(p.s) && p.s[p.i] == '\\' && p.s[p.i+1] == 'u' {
					if lo, ok := hex4(p.s[p.i+2:]); ok && lo >= 0xDC00 && lo <= 0xDFFF {
						p.i += 6
						sb.WriteRune(utf16.DecodeRune(r, lo))
						break
					}
				}
				lone = true // the next escape, if any, is read on its own
			default:
				return "", false, errors.New("bad escape")
			}
		default:
			r, n := utf8.DecodeRune(p.s[p.i:])
			if r == utf8.RuneError && n <= 1 {
				return "", false, errors.New("invalid UTF-8")
			}
			sb.Write(p.s[p.i : p.i+n])
			p.i += n
		}
	}
}

var numberShape = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?`)

func (p *parser) number() (any, error) {
	m := numberShape.Find(p.s[p.i:])
	if m == nil {
		return nil, errors.New("bad number")
	}
	p.i += len(m)
	return number(m), nil
}

// containsNull is ProtocolJson.ContainsNull: every occurrence of every member, at any depth.
func containsNull(v any) bool {
	switch x := v.(type) {
	case null:
		return true
	case object:
		for _, vs := range x.m {
			for _, e := range vs {
				if containsNull(e) {
					return true
				}
			}
		}
	case []any:
		for _, e := range x {
			if containsNull(e) {
				return true
			}
		}
	}
	return false
}

// ---------------------------------------------------------------------------------------------------- checks

func ptr(v int64) *int64 { return &v }

func (o object) has(name string) bool { return len(o.m[name]) > 0 }

func (o object) only(allowed, required []string) error {
	for k := range o.m {
		found := false
		for _, a := range allowed {
			if k == a {
				found = true
				break
			}
		}
		if !found {
			return errors.New("unexpected property") // the name is the peer's: never echoed
		}
	}
	for _, r := range required {
		if !o.has(r) {
			return fmt.Errorf("%s: missing", r)
		}
	}
	return nil
}

// utf16Len is a string's length in UTF-16 code units (C# string.Length, JavaScript's length: the schema's maxLength).
func utf16Len(s string) int {
	n := 0
	for _, r := range s {
		n += utf16.RuneLen(r)
	}
	return n
}

// earlier checks the occurrences before the last one with ok (each is read by System.Text.Json: its JSON type must fit).
func (o object) earlier(name string, ok func(any) bool) error {
	vs := o.m[name]
	for _, v := range vs[:max(len(vs)-1, 0)] {
		if !ok(v) {
			return fmt.Errorf("%s: a repeated value of the wrong type", name)
		}
	}
	return nil
}

func isString(v any) bool { _, ok := v.(string); return ok }

func isInt64(v any) bool {
	n, ok := v.(number)
	if !ok {
		return false
	}
	_, err := strconv.ParseInt(string(n), 10, 64)
	return err == nil
}

func (o object) str(name string, re *regexp.Regexp, maxLength int) (string, error) {
	if err := o.earlier(name, isString); err != nil {
		return "", err
	}
	s, ok := o.last(name).(string)
	if !ok {
		return "", fmt.Errorf("%s: expected string", name)
	}
	if maxLength >= 0 && utf16Len(s) > maxLength {
		return "", fmt.Errorf("%s: longer than %d", name, maxLength)
	}
	if re != nil && !re.MatchString(s) {
		return "", fmt.Errorf("%s: does not match the pattern", name)
	}
	return s, nil
}

func (o object) integer(name string, minimum, maximum *int64) (int64, error) {
	if err := o.earlier(name, isInt64); err != nil {
		return 0, err
	}
	n, ok := o.last(name).(number)
	if !ok {
		return 0, fmt.Errorf("%s: expected an integer", name)
	}
	// the reader's number literal plus ParseInt: no fraction, no exponent (as System.Text.Json reads an Int64)
	v, err := strconv.ParseInt(string(n), 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%s: expected an integer", name)
	}
	if v > maxSafe || v < -maxSafe {
		return 0, fmt.Errorf("%s: outside the safe integer range", name)
	}
	if minimum != nil && v < *minimum {
		return 0, fmt.Errorf("%s: below %d", name, *minimum)
	}
	if maximum != nil && v > *maximum {
		return 0, fmt.Errorf("%s: above %d", name, *maximum)
	}
	return v, nil
}

func (o object) boolean(name string) (bool, error) {
	if err := o.earlier(name, func(v any) bool { _, ok := v.(bool); return ok }); err != nil {
		return false, err
	}
	b, ok := o.last(name).(bool)
	if !ok {
		return false, fmt.Errorf("%s: expected boolean", name)
	}
	return b, nil
}

func (o object) enum(name string, values map[string]bool) (string, error) {
	allowed := func(v any) bool { s, ok := v.(string); return ok && values[s] }
	if err := o.earlier(name, allowed); err != nil {
		return "", err
	}
	if v := o.last(name); !allowed(v) {
		return "", fmt.Errorf("%s: not an allowed value", name)
	}
	return o.last(name).(string), nil
}

// ---------------------------------------------------------------------------------------------------- writing

type writer struct{ b []byte }

func (w *writer) begin(t string) {
	w.b = append(w.b, `{"type":`...)
	w.b = appendString(w.b, t)
}

func (w *writer) name(n string) {
	w.b = append(w.b, ',')
	w.b = appendString(w.b, n)
	w.b = append(w.b, ':')
}

func (w *writer) str(n, v string) {
	w.name(n)
	w.b = appendString(w.b, v)
}

func (w *writer) integer(n string, v int64) {
	w.name(n)
	w.b = strconv.AppendInt(w.b, v, 10)
}

func (w *writer) boolean(n string, v bool) {
	w.name(n)
	w.b = strconv.AppendBool(w.b, v)
}

func (w *writer) end() { w.b = append(w.b, '}') }

// appendString writes a JSON string: quote, backslash and control characters escaped, everything else as UTF-8.
func appendString(b []byte, s string) []byte {
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		switch c := s[i]; {
		case c == '"':
			b = append(b, '\\', '"')
		case c == '\\':
			b = append(b, '\\', '\\')
		case c < 0x20:
			b = append(b, fmt.Sprintf(`\u%04x`, c)...)
		default:
			b = append(b, c)
		}
	}
	return append(b, '"')
}
